// kernel/file.h 中的内存 inode 结构
struct inode {
  uint dev;           // Device number
  uint inum;          // Inode number
  int ref;            // Reference count
  int nlink;          // 硬链接计数（本次实验新增）
  struct sleeplock lock;
  int valid;          // Has been read from disk?
  short type;         // copy of disk inode
  // ... 其他字段
};

// kernel/fs.h 中的磁盘 inode 结构  
struct dinode {
  short type;         // File type
  short major;        // Major device number (T_DEVICE only)
  short minor;        // Minor device number (T_DEVICE only)
  short nlink;        // Number of links to inode in file system
  uint size;          // Size of file (bytes)
  uint addrs[NDIRECT+1]; // Data block addresses
};

uint64
sys_linkat(void)
{
  char new[MAXPATH], old[MAXPATH];
  struct inode *dp, *ip;

  // 获取 oldpath 对应的 inode
  if(argstr(0, old, MAXPATH) < 0 || (ip = namei(old)) == 0)
    return -1;

  ivalid(ip);
  if(ip->type == T_DIR) {  // 不允许硬链接到目录
    iput(ip);
    return -1;
  }

  // 获取 newpath 的父目录和文件名
  if(argstr(1, new, MAXPATH) < 0 || (dp = nameiparent(new, name)) == 0) {
    iput(ip);
    return -1;
  }

  // 检查：新旧路径是否指向同一文件？
  if(ip->dev == dp->dev && ip->inum == namei(new)->inum) {
    iput(dp);
    iput(ip);
    return -1;
  }

  // 创建新的目录项
  if(dirlink(dp, name, ip->inum) < 0) {
    iput(dp);
    iput(ip);
    return -1;
  }

  ip->nlink++;
  iupdate(ip);
  iput(ip);
  iput(dp);
  return 0;
}

// sys_unlinkat 中删除链接的部分
if(ip->nlink < 1)
  panic("unlink: nlink < 1");
memmove(de.name, ".", DIRSIZ);  // 清除目录项
writei(dp, 0, (uint64)&de, off, sizeof(de));
ip->nlink--;
iupdate(ip);
iput(ip);  // 关键调用

// 修改后的 iput 函数
void
iput(struct inode *ip)
{
  acquire(&itable.lock);
  if(ip->ref == 1 && ip->valid && ip->nlink == 0){
    // 当最后一个引用且没有硬链接时，释放文件内容
    release(&itable.lock);
    ivalid(ip);
    itrunc(ip);      // 释放数据块
    ip->type = 0;    // 标记为空闲
    iupdate(ip);     // 写回磁盘
    ip->flags = 0;
    ip->valid = 0;
    acquire(&itable.lock);
  }
  ip->ref--;
  release(&itable.lock);
}

uint64
sys_fstat(void)
{
  struct file *f;
  uint64 st;  // user pointer to struct stat

  if(argfd(0, 0, &f) < 0 || argaddr(1, &st) < 0)
    return -1;

  struct stat kst;
  kst.dev = f->ip->dev;
  kst.ino = f->ip->inum;
  kst.mode = (f->ip->type == T_DIR) ? DIR : 
             (f->ip->type == T_FILE) ? FILE : 0;
  kst.nlink = f->ip->nlink;  // 获取硬链接数

  // 填充 pad（清零）
  for(int i = 0; i < 7; i++) kst.pad[i] = 0;

  if(copyout(myproc()->pagetable, st, (char *)&kst, sizeof(kst)) < 0)
    return -1;
  return 0;
}

